pm.test("Existing room returns 200", function (){
    pm.response.to.have.status(200);
});

pm.test("Room has a room ID", function(){
    const response = pm.response.json();
    pm.expect(response.roomid || response.roomid).to.exist;
});

pm.test("Room ID is a positive integer", function(){
    const response  = pm.response.json();
    pm.expect(response.roomid).to.be.a("number");
    pm.expect(Number.isInteger(response.roomid)).to.eql(true);
    pm.expect(response.roomid).to.be.greaterThan(0);
});

pm.test("Returned room ID matches the requested ID", function(){
    const response = pm.response.json();
    pm.expect(response.roomid).to.eql(Number(pm.variables.get("roomId")));
});

pm.test("Room has all required fields", function(){
    const response = pm.response.json();
    pm.expect(response).to.have.property("roomid");
    pm.expect(response).to.have.property("roomName");
    pm.expect(response).to.have.property("roomPrice");
    pm.expect(response).to.have.property("type");
});

pm.test("Room price is  positive number", function(){
    const response = pm.response.json();
    pm.expect(response.roomPrice).to.be.a("number");
    pm.expect(response.roomPrice).to.be.greaterThan(0);
});

pm.test("Response contains the rooms property", function(){
    const response = pm.response.json();

    pm.expect(response).to.have.property("rooms");
    pm.expect(response.rooms).to.be.an("array");
});

pm.test("Response contains at least one room", function(){
    const response = pm.response.json();

    pm.expect(response.rooms).to.be.an("array");
    pm.expect(response.rooms.length).to.be.greaterThan(0);
})

pm.test("Each room has the required fields", function(){
    const response = pm.response.json();

    response.rooms.forEach(function(room){
        pm.expect(room).to.have.property("roomid");
        pm.expect(room).to.have.property("roomName");
        pm.expect(room).to.have.property("roomPrice");
        pm.expect(room).to.have.property("type");
    });
});

pm.test("Room fields have valid data types", function(){
    const response = pm.response.json();

    response.rooms.forEach(function(room){
        pm.expect(room.roomid).to.be.a("number");
        pm.expect(room.roomName).to.be.a("string");
        pm.expect(room.roomPrice).to.be.a("number");
        pm.expect(room.type).to.be.a("string");
    });
});

pm.test("Response returns the expected status", function (){
    pm.response.to.have.status(500);
});

pm.test("Error response includes the correct path", function(){
    const response = pm.response.json();
    pm.expect(response.path).to.eql("/room/4");
});
